previewCss:
.darma-loader-darma-b15-seed-pod-burst { --accent: var(--loader-color, #65a30d); --accent-2: var(--loader-secondary-color, #fef08a); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b15-seed-pod-burst .darma-loader-darma-b15-seed-pod-burst__half { position: absolute; left: 32%; top: 30%; width: 36%; height: 40%; background: linear-gradient(var(--accent-2), var(--accent)); }
.darma-loader-darma-b15-seed-pod-burst .darma-loader-darma-b15-seed-pod-burst__half:nth-of-type(1) { border-radius: 100% 0 0 100% / 50% 0 0 50%; transform-origin: 100% 50%; animation: darma-loader-darma-b15-seed-pod-burst-pod-open-left calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b15-seed-pod-burst .darma-loader-darma-b15-seed-pod-burst__half:nth-of-type(2) { border-radius: 0 100% 100% 0 / 0 50% 50% 0; transform-origin: 0 50%; animation: darma-loader-darma-b15-seed-pod-burst-pod-open-right calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b15-seed-pod-burst i { position: absolute; left: 46%; top: 46%; width: 8%; height: 8%; border-radius: 50% 50% 50% 0; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b15-seed-pod-burst-pod-seed calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.2, .7, .4, 1) infinite; }
.darma-loader-darma-b15-seed-pod-burst i:nth-of-type(1) { --dx: -230%; --dy: -180%; }
.darma-loader-darma-b15-seed-pod-burst i:nth-of-type(2) { --dx: 240%; --dy: -170%; }
.darma-loader-darma-b15-seed-pod-burst i:nth-of-type(3) { --dx: -190%; --dy: 210%; }
.darma-loader-darma-b15-seed-pod-burst i:nth-of-type(4) { --dx: 220%; --dy: 200%; }
@keyframes darma-loader-darma-b15-seed-pod-burst-pod-open-left { 0%, 30% { transform: rotate(0deg); } 55%, 78% { transform: rotate(-58deg); } 100% { transform: rotate(0deg); } }
@keyframes darma-loader-darma-b15-seed-pod-burst-pod-open-right { 0%, 30% { transform: rotate(0deg); } 55%, 78% { transform: rotate(58deg); } 100% { transform: rotate(0deg); } }
@keyframes darma-loader-darma-b15-seed-pod-burst-pod-seed { 0%, 38% { opacity: 0; transform: translate(0, 0) scale(.4); } 48% { opacity: 1; transform: translate(0, 0) scale(1); } 88%, 100% { opacity: 0; transform: translate(var(--dx, 0%), var(--dy, 0%)) scale(.6); } }

